-- Scoped My Current Load / 3D CMS copy contract. Only the whitelist and required text templates are extended. Existing permissions, review, placeholder and asset validation remain intact.
CREATE OR REPLACE FUNCTION public.konsoliss_validate_homepage_content()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare required_labels jsonb := '{"home.brand":"Konsoliss","home.load.heading":"My current load","home.available":"available","home.otherCargo":"Other cargo","home.yourSpace":"Your space","home.free":"Free","home.book.title":"Book Space","home.book.subtitle":"Reserve container capacity","home.load.title":"Load Items","home.load.subtitle":"Move warehouse goods","home.calc.title":"CBM Calculator","home.calc.subtitle":"Calculate your package volume","home.warehouse.title":"Warehouse","home.consolidated.title":"Consolidated","home.sourcing.title":"Sourcing+","home.sourcing.subtitle":"Find products, compare prices, get them delivered","home.how.heading":"How consolidation works","home.how.1.title":"Book Space","home.how.1.body":"Reserve the CBM you need for your shipment.\nStarting from 0.02 CBM","home.how.2.title":"Inbound to warehouse","home.how.2.body":"Buy on WANTISS, \npaste a product link \nfor us to purchase,\nor ship external items \nto our warehouse.","home.how.3.title":"Items processing","home.how.3.body":"We verify incoming items \nand optimize packaging \nwhen needed","home.how.4.title":"Load items","home.how.4.body":"Allocate items \nto your reserved space","home.how.5.title":"Container departs","home.how.5.body":"Your orders are shipped \nand delivered to you \nor ready for pickup \nat a designated location","book.heading":"Book Space","calc.heading":"CBM calculator","calc.instructions":"Enter size in cm","calc.length":"Length","calc.width":"Width","calc.height":"Height","calc.quantity":"Quantity","nav.home":"Home","nav.warehouse":"Warehouse","nav.consolidated":"Konso","nav.sourcing":"Sourcing+","nav.hub":"Hub","common.back":"Back","common.close":"Close","common.cancel":"Cancel","common.retry":"Retry","common.send":"Send request","common.sending":"Sending…","status.loading":"Loading container…","status.unassigned":"No active load","status.unavailable":"Container unavailable","status.preparing":"Preparing your load","status.filling":"Filling","status.filled":"Filled","status.departed":"Departed","status.arrived":"Arrived","home.noAssignment":"No container assigned","home.filled":"{percent} filled","home.loadedInbound":"Loaded {loaded} · Inbound {inbound} CBM","home.loading":"Loading your container…","home.noAccountContainer":"No container assigned to your account","home.measurementsUnavailable":"Verified container measurements are not available yet","load.loaded":"Loaded","load.inbound":"Inbound","load.notAllocated":"Not allocated","load.breakdown":"My space breakdown","load.reserved":"Space purchased","load.sent":"Goods sent","load.physical":"Physically loaded in container","load.inboundDetail":"Inbound to container (not yet physically loaded)","load.allocated":"Loaded + inbound","load.warehouseTransit":"At warehouse or still in transit","load.notSent":"Purchased space not yet sent","load.notCommitted":"Space not yet loaded or inbound","load.explanation":"Loaded and inbound count toward your purchased space. Goods still at the warehouse or in transit do not count as loaded or inbound to the container.","warehouse.amount":"{volume} CBM sent, not yet allocated","warehouse.empty":"No goods sent yet","warehouse.unavailable":"Warehouse volume not yet recorded","container.detailsUnavailable":"Load details unavailable","container.choose":"Choose container","container.count":"{count} assigned container(s)","book.capacity":"Container capacity: {capacity} CBM. Live free space must be confirmed before booking.","book.unavailable":"Booking is unavailable until a verified quote, capacity reservation and payment service are configured. No reservation or payment has been made.","calc.estimate":"Estimated volume: {volume} CBM","calc.disclaimer":"Volume estimate only. Physical fit also depends on orientation, weight, stacking and handling. Pricing requires a verified quote.","calc.invalid":"Enter positive dimensions and a whole-number quantity.","menu.home":"Home","menu.messages":"Messages","menu.notifications":"Notifications","menu.wallet":"Wallet","menu.saved":"Saved","menu.orders":"My Orders","menu.activity":"Recent Activity","menu.help":"Help Center","menu.feedback":"Feedback","menu.business":"Business Space","menu.dark":"Dark Mode","menu.unreadUnavailable":"Unread counts unavailable · Retry","panel.warehouse":"Warehouse cargo","panel.load":"Cargo handling","panel.sourcing":"Sourcing request","panel.hub":"Konsoliss Hub","panel.orders":"Shipment history","panel.loadInfo":"Cargo handling is verified by warehouse staff. Review your recorded quantities or send the team a handling request.","panel.sourcingInfo":"Send the team your product links and requirements. A support ticket does not place an order or charge your account.","panel.ordersInfo":"Shipment-level history is not available here yet. Your assigned containers and verified cargo quantities are shown on the homepage.","support.heading":"Konsoliss support","support.feedback":"Konsoliss feedback","support.subject":"Subject","support.message":"Message","support.sent":"Request received: {ticket}","support.error":"Your request could not be confirmed. Your message is preserved. Please retry.","support.required":"Enter a subject and message.","support.contact":"Contact the team","support.info":"Include the relevant container number and cargo details. Never send passwords or payment credentials.","theme.error":"Your theme preference could not be saved. Please try again.","canvas.current":"My current loaded space","canvas.free":"{volume} CBM free","canvas.ceiling":"Ceiling {height} m","lifecycle.filling.title":"Container filling","lifecycle.filling.description":"Your container is currently accepting and loading cargo. You can follow its progress while space is available.","lifecycle.filled.title":"Container filled","lifecycle.filled.description":"Loading for this container is complete and no more cargo can be added. It is being prepared for departure.","lifecycle.departed.title":"Container departed","lifecycle.departed.description":"Your container has left its departure location and is on the way to its destination. You can follow its shipment progress here.","lifecycle.arrived.title":"Container arrived","lifecycle.arrived.description":"Your container has reached its destination. Individual packages may still need customs processing, delivery, or pickup.","a11y.back":"Back","a11y.chooseContainer":"Choose container","a11y.openContainers":"Open your assigned containers","a11y.loadDetails":"My current load details","a11y.progress":"Show other progress bar","a11y.progressHint":"Toggle between cargo loading and container allocation","a11y.consolidated":"Choose consolidated container","a11y.quickMenu":"Open Konsoliss quick menu","a11y.closeDetails":"Close current load details","a11y.closeBreakdown":"Close load breakdown","a11y.closeList":"Close container list","a11y.closeSelector":"Close container selector","a11y.selectContainer":"Select container {number}","a11y.explainContainer":"Explain status of {number}","a11y.dismissStatus":"Dismiss container status explanation","a11y.statusExplanation":"Container status explanation","a11y.closeStatus":"Close container status explanation","a11y.closeMenu":"Close Konsoliss menu","lifecycle.hint":"This notice closes automatically. Tap the container status anytime to read it again.","load.nothingSent":"Nothing sent","load.labelCreated":"Label created","load.warehouseInbound":"Inbound to warehouse • {volume} CBM","load.atWarehouse":"{volume} CBM at warehouse","load.inboundWarehousePart":"{volume} CBM inbound to warehouse","load.notSentVolume":"{volume} CBM not sent","load.allocatedNotLoaded":"{volume} CBM allocated • Not loaded","load.loadedVolume":"{volume} CBM loaded","load.inboundVolume":"{volume} CBM inbound","load.unassignedVolume":"{volume} CBM unassigned","load.remainingVolume":"{volume} CBM remaining","load.unusedVolume":"{volume} CBM unused","load.split":"Split into {count} containers","load.preparingShipment":"Preparing shipment","load.incident":"Incident under review","load.expired":"Reservation expired","load.awaitingCustoms":"Arrived • Awaiting customs clearance","load.illustration":"Illustration · not a real container","load.loading":"Loading…","load.unavailable":"Data unavailable","deadline.reminder":"Send goods and upload tracking","deadline.reached":"Deadline reached","deadline.days":"{days}d ","deadline.clock":"{hours}h {minutes}m {seconds}s left","deadline.clockDays":"{days}{hours}h {minutes}m {seconds}s left","container.notAssigned":"Not assigned yet","container.unassignedCaption":"Not assigned to a container yet: {volume} CBM","canvas.reservedHere":"{volume} CBM reserved here · not loaded yet","canvas.preview":"{label} {volume} CBM","a11y.unassigned":"Show unassigned purchased space"}'::jsonb; k text; v text; expected text[]; actual text[];
begin
 if new.content_key<>'konsoliss.content' then return new;end if;
 if new.locale is null or new.locale not in ('en','fr','ht','es','zh-Hans') or new.payload->>'v' is distinct from '2'
 or jsonb_typeof(new.payload->'labels') is distinct from 'object'
 or jsonb_typeof(new.payload->'reviewed') is distinct from 'array'
 or jsonb_typeof(new.payload->'images') is distinct from 'object'
 then raise exception 'Invalid Konsoliss homepage schema or locale' using errcode='22023';end if;
 if exists(select 1 from jsonb_object_keys(new.payload) as x(key) where key not in ('v','labels','reviewed','images'))
 or exists(select 1 from jsonb_object_keys(new.payload->'labels') as x(key) where not required_labels ? key)
 then raise exception 'Homepage content cannot contain operational fields or unknown labels' using errcode='22023';end if;
 if exists(select 1 from jsonb_each(new.payload->'labels') as x(key,value) where jsonb_typeof(value)<>'string' or length(value#>>'{}')>4000) then raise exception 'Labels must be text up to 4000 characters' using errcode='22023';end if;
 for k,v in select key,value from jsonb_each_text(new.payload->'images') loop
  if not k=any(array['how.1','how.2','how.3','how.4','how.5','nav.home','nav.warehouse','nav.consolidated','nav.sourcing','nav.hub','menu.logo']) or v !~ '^konsoliss\.[a-zA-Z0-9._-]+$' then raise exception 'Invalid image slot or asset key' using errcode='22023';end if;
  if new.status='published' and not exists(select 1 from public.wantiss_cms_assets a where a.asset_key=v and a.status='published' and a.content_type like 'image/%') then raise exception 'Publish referenced image assets first' using errcode='22023';end if;
 end loop;
 if new.status='published' then
  for k,v in select key,value from jsonb_each_text(required_labels) loop
   if jsonb_typeof(new.payload->'labels'->k) is distinct from 'string' or length(trim(new.payload->'labels'->>k)) not between 1 and 4000 or not (new.payload->'reviewed') ? k then
    raise exception 'Konsoliss text % needs translation review',k using errcode='22023';
   end if;
   select coalesce(array_agg(m[1] order by m[1]),array[]::text[]) into expected from regexp_matches(v,'\{([a-zA-Z][a-zA-Z0-9]*)\}','g') as m;
   select coalesce(array_agg(m[1] order by m[1]),array[]::text[]) into actual from regexp_matches(new.payload->'labels'->>k,'\{([a-zA-Z][a-zA-Z0-9]*)\}','g') as m;
   if actual<>expected then raise exception 'Preserve placeholders in %',k using errcode='22023';end if;
  end loop;
 end if;
 return new;
end $function$;
revoke all on function public.konsoliss_validate_homepage_content() from public,anon,authenticated;
